public class Main {
    static String joinComma(String[] parts) {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < parts.length; i++) {
            if (i > 0) b.append(",");
            b.append(parts[i]);
        }
        return b.toString();
    }
    public static void main(String[] args) {
        System.out.println(joinComma(new String[]{"a", "b"}));
    }
}

